import{_ as d,o as a,c as r,a2 as h}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"اہم شخصیات اور تنظیمیں","description":"","frontmatter":{},"headers":[],"relativePath":"ur/95-关键人物与组织.md","filePath":"ur/95-关键人物与组织.md"}'),e={name:"ur/95-关键人物与组织.md"};function o(l,t,i,b,n,u){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="اہم-شخصیات-اور-تنظیمیں" tabindex="-1">اہم شخصیات اور تنظیمیں <a class="header-anchor" href="#اہم-شخصیات-اور-تنظیمیں" aria-label="Permalink to &quot;اہم شخصیات اور تنظیمیں&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>95</td></tr><tr><td>ماڈیول</td><td>ضمائم اور حوالہ جاتی مواد</td></tr><tr><td>بنیادی الفاظ</td><td>اہم شخصیات، اہم تنظیمیں، تاریخی کردار، اداروں کے کام، سمبیوسس تہذیب</td></tr></tbody></table><h2 id="۱-وضاحت" tabindex="-1">۱. وضاحت <a class="header-anchor" href="#۱-وضاحت" aria-label="Permalink to &quot;۱. وضاحت&quot;">​</a></h2><p>اس دستاویز میں اینکر سمبیوسس تہذیب کی ترقی کے راستے میں اہم شخصیات اور اہم تنظیمیں شامل ہیں، تاریخی دور اور تنظیم کی قسم کے لحاظ سے درجہ بندی کی گئی ہیں۔ اہم شخصیات کے حصے میں شخص کا نام، دور، بنیادی شراکت اور تاریخی مقام درج ہے؛ اہم تنظیموں کے حصے میں تنظیم کا نام، قیام کا وقت، بنیادی کام اور تاریخی کردار درج ہے۔ یہ دستاویز ایک متحرک اپ ڈیٹ دستاویز ہے؛ تاریخ کی پیشرفت اور تنظیموں کے ارتقاء کے ساتھ ساتھ مسلسل اضافے اور ترمیم کی جائے گی۔</p><h2 id="۲-اہم-شخصیات" tabindex="-1">۲. اہم شخصیات <a class="header-anchor" href="#۲-اہم-شخصیات" aria-label="Permalink to &quot;۲. اہم شخصیات&quot;">​</a></h2><h3 id="۲-۱-پری-اینکر-دور-کے-فکری-پیش-رو" tabindex="-1">۲.۱ پری اینکر دور کے فکری پیش رو <a class="header-anchor" href="#۲-۱-پری-اینکر-دور-کے-فکری-پیش-رو" aria-label="Permalink to &quot;۲.۱ پری اینکر دور کے فکری پیش رو&quot;">​</a></h3><table tabindex="0"><thead><tr><th>شخص کا نام</th><th>دور</th><th>بنیادی شراکت</th><th>تاریخی مقام</th></tr></thead><tbody><tr><td>ژوان ہینگ زی</td><td>تقریباً -500 ملین سال</td><td>پہلا مفکر جس نے لوٹ مار کے انداز کی کھیت کے نظام پر منظم طریقے سے غور و فکر کیا، &quot;سمبیوسس&quot; تصور کا ابتدائی روپ تجویز کیا، &quot;اینٹی لوٹ مار تھیوری&quot; کے نامکمل حصے کے مصنف</td><td>سمبیوسس فکر کے قدیم پیش رو، جن کی فکر کروڑوں سال کی نیند کے بعد اینکر سمبیوسس تہذیب کا روحانی ماخذ بنی</td></tr><tr><td>وان لنگ مو</td><td>تقریباً -100 ملین سال</td><td>پہلی بڑی پیمانے کی سمبیوسس تجرباتی تہذیب کی قیادت کی؛ حالانکہ آخر کار لوٹ مار کے انداز کی تہذیب کے ذریعے تباہ کر دیا گیا، لیکن اس کی مشق نے سمبیوسس نظام کی امکانات کو ثابت کیا</td><td>سمبیوسس مشق کے پیش رو، بعد کی نسلوں کی طرف سے &quot;سمبیوسس کی ماں&quot; کے طور پر احترام کیا جاتا ہے</td></tr><tr><td>ماؤ جوے ژھے</td><td>تقریباً -10,000 سال</td><td>پہلے طیارے کا ایک کھیت کار، طویل مدتی کھیت کے دوران اتفاق سے قوانین کے نیٹ ورک میں مستحکم نوڈس کو محسوس کیا، اینکر میکانزم دریافت کیا</td><td>اینکر میکانزم کے دریافت کنندہ، اینکر بیداری دور کے آغاز کنندہ</td></tr></tbody></table><h3 id="۲-۲-اینکر-بیداری-دور-کے-بانی" tabindex="-1">۲.۲ اینکر بیداری دور کے بانی <a class="header-anchor" href="#۲-۲-اینکر-بیداری-دور-کے-بانی" aria-label="Permalink to &quot;۲.۲ اینکر بیداری دور کے بانی&quot;">​</a></h3><table tabindex="0"><thead><tr><th>شخص کا نام</th><th>دور</th><th>بنیادی شراکت</th><th>تاریخی مقام</th></tr></thead><tbody><tr><td>ماؤ دنگ گونگ</td><td>-10000 سے -9200 سال</td><td>ماؤ جوے ژھے کے شاگرد، اینکر میکانزم پر منظم تحقیق کی، پہلا مصنوعی اینکر بنایا، &quot;اینکر اصول&quot; کے مصنف</td><td>اینکر ٹیکنالوجی کے بانی، مصنوعی اینکر کے موجد</td></tr><tr><td>گونگ شینگ زی</td><td>-6000 سے -5100 سال</td><td>اینکر ٹیکنالوجی کو سمبیوسس فکر کے ساتھ جوڑا، &quot;اینکر سمبیوسس&quot; نظریاتی نظام بنایا، &quot;اینکر سمبیوسس تھیوری&quot; کے مصنف</td><td>اینکر سمبیوسس تھیوری کے بانی، سمبیوسس تہذیب کے روحانی گرو</td></tr><tr><td>ہینگ یوان گونگ</td><td>-5000 سے -4300 سال</td><td>اینکر پر مبنی پہلی سمبیوسس قسم کی شہر ریاست &quot;ہینگ یوان سٹی&quot; کی بنیاد رکھی، اور لوٹ مار کے انداز کی تہذیب کے حملے کو کامیابی سے دبایا</td><td>پہلی سمبیوسس قسم کی شہر ریاست کے بانی، سمبیوسس نظام کے عمل کرنے والے</td></tr><tr><td>وان زو شی</td><td>-2000 سے -1200 سال</td><td>پہلی &quot;تمام نسلوں کی سمبیوسس کانفرنس&quot; شروع کی، درجنوں نسلوں کے درمیان سمبیوسس اتحاد کی وکالت کی</td><td>تمام نسلوں کے اتحاد کے وکیل، بین نسلی سمبیوسس کے پیش رو</td></tr></tbody></table><h3 id="۲-۳-سمبیوسس-نظام-کے-قیام-کے-دور-کے-ریاست-کے-بانی" tabindex="-1">۲.۳ سمبیوسس نظام کے قیام کے دور کے ریاست کے بانی <a class="header-anchor" href="#۲-۳-سمبیوسس-نظام-کے-قیام-کے-دور-کے-ریاست-کے-بانی" aria-label="Permalink to &quot;۲.۳ سمبیوسس نظام کے قیام کے دور کے ریاست کے بانی&quot;">​</a></h3><table tabindex="0"><thead><tr><th>شخص کا نام</th><th>دور</th><th>بنیادی شراکت</th><th>تاریخی مقام</th></tr></thead><tbody><tr><td>لی شیان گونگ</td><td>-1000 سے -900 سال</td><td>سمبیوسس آئین مسودہ کمیٹی کے صدر، &quot;سمبیوسس آئین&quot; کی مسودہ تیاری کی قیادت کی، آئین کے عوامی ریفرنڈم کے ذریعے منظور ہونے کو فروغ دیا</td><td>سمبیوسس آئین کے مرکزی مسودہ نویس، سمبیوسس تہذیب کے آئینی باپ</td></tr><tr><td>جی فا گونگ</td><td>-900 سے -780 سال</td><td>پہلے سمبیوسس عملدرآمد کمیٹی کے صدر، سمبیوسس تہذیب کے انتظامی نظام اور قانون کے نفاذ کے طریقہ کار کو قائم کیا</td><td>سمبیوسس انتظامی نظام کے بانی، پہلا انتظامی سربراہ</td></tr><tr><td>سی فا مو</td><td>-900 سے -800 سال</td><td>پہلے سمبیوسس عدالت کے چیف جسٹس، سمبیوسس تہذیب کے عدالتی نظام اور غیر آئینی جائزے کے نظام کو قائم کیا</td><td>سمبیوسس عدالتی نظام کے بانی، پہلی عدالتی سربراہ</td></tr><tr><td>سان بائی شی</td><td>-500 سے -300 سال</td><td>تین سو سیٹ اصل کھیت نظام کی کھدائی اور تنظیم کے کام کی قیادت کی، ٹیم کی قیادت میں تمام تین سو سیٹ نظام کی تصدیق مکمل کی</td><td>تین سو سیٹ نظام کے عمومی منظم، کھیت کھولنے کے منصوبے کے جنرل کمانڈر</td></tr><tr><td>بئی زینگ گونگ</td><td>-300 سے -220 سال</td><td>دوگنا پھل کی تکنیکی اطلاق تحقیق کی قیادت کی، سو گنا قیاس اضافے کی ٹیکنالوجی کی انجینئرنگ پیش رفت حاصل کی</td><td>دوگنا پھل ٹیکنیکلائزیشن کے چیف سائنٹسٹ، قیاس تکرار نظام کے فروغ دینے والے</td></tr></tbody></table><h3 id="۲-۴-کھولنے-اور-چالو-کرنے-کے-دور-کے-رہنما" tabindex="-1">۲.۴ کھولنے اور چالو کرنے کے دور کے رہنما <a class="header-anchor" href="#۲-۴-کھولنے-اور-چالو-کرنے-کے-دور-کے-رہنما" aria-label="Permalink to &quot;۲.۴ کھولنے اور چالو کرنے کے دور کے رہنما&quot;">​</a></h3><table tabindex="0"><thead><tr><th>شخص کا نام</th><th>دور</th><th>بنیادی شراکت</th><th>تاریخی مقام</th></tr></thead><tbody><tr><td>کائی فانگ گونگ</td><td>-100 سے -50 سال</td><td>تین سو سیٹ اصل کھیت نظام کے مکمل کھولنے کے کام کی قیادت کی، کھیت وسائل کی تقسیم کا نظام اور گرو نیٹ ورک قائم کیا</td><td>تین سو سیٹ نظام کھولنے کے جنرل کمانڈر، &quot;ہر ایک کے پاس راستہ ہے&quot; کے عمل کرنے والے</td></tr><tr><td>جی ہو گونگ</td><td>-50 سال سے اصل سال</td><td>20% چالو کرنے کی حکمت عملی کے نفاذ کی قیادت کی، ٹیم کی قیادت میں 50 سال میں 20% مخلوقات کے چالو کرنے کے ہدف کو مکمل کیا</td><td>20% چالو کرنے کی حکمت عملی کے جنرل کمانڈر، سمبیوسس تہذیب کے نئے دور کے آغاز کنندہ</td></tr><tr><td>شینگ وے گونگ</td><td>اصل سال سے 80 سال</td><td>پہلی جہت بڑھانے کے منصوبے کی قیادت کی، چار مرحلے جہت بڑھانے کے راستے کے نفاذ کو فروغ دیا، پہلی مرحلہ وار جہت بڑھاؤ حاصل کیا</td><td>پہلی جہت بڑھانے کے جنرل انجینئر، جہت بڑھانے کے دور کے رہنما</td></tr></tbody></table><h3 id="۲-۵-تمام-نسلوں-کی-جمہوریہ-اور-بین-طیاروں-کے-دور-کے-متلاشی" tabindex="-1">۲.۵ تمام نسلوں کی جمہوریہ اور بین طیاروں کے دور کے متلاشی <a class="header-anchor" href="#۲-۵-تمام-نسلوں-کی-جمہوریہ-اور-بین-طیاروں-کے-دور-کے-متلاشی" aria-label="Permalink to &quot;۲.۵ تمام نسلوں کی جمہوریہ اور بین طیاروں کے دور کے متلاشی&quot;">​</a></h3><table tabindex="0"><thead><tr><th>شخص کا نام</th><th>دور</th><th>بنیادی شراکت</th><th>تاریخی مقام</th></tr></thead><tbody><tr><td>وان زو گونگ ژو</td><td>100 سے 200 سال</td><td>تمام نسلوں کی جمہوریہ کے قیام کے کام کی قیادت کی، تمام نسلوں کی فہرست کی تدوین اور بین نسلی مرکب کی پالیسی کو فروغ دیا</td><td>تمام نسلوں کی جمہوریہ کے بانی، پہلے تمام نسلوں کی جمہوریہ کے سربراہ</td></tr><tr><td>وے میان مو</td><td>500 سے 650 سال</td><td>پہلی طیارہ انتظامیہ کے ڈائریکٹر، بڑی پیمانے کی بین طیاروں دریافت منصوبے کی قیادت کی، طیارہ کوآرڈینیٹس کا عمومی بینک قائم کیا</td><td>بین طیاروں دریافت کے آغاز کنندہ، طیارہ انتظامی نظام کے بانی</td></tr><tr><td>کاؤ گو گونگ</td><td>800 سے 950 سال</td><td>کاپی آئینے دور دراز آثار قدیمہ کے منصوبے کی حتمی پختگی کی قیادت کی، بین طیاروں آثار قدیمہ کو پیمانے کے دور میں داخل ہونے کو فروغ دیا</td><td>آثار قدیمہ کے منصوبے کے مجموعی کامیابی کے حقدار، بین طیاروں آثار قدیمہ کے بانی</td></tr><tr><td>شی لو گونگ</td><td>1000 سے 1150 سال</td><td>وقت کے پیچھے ہٹنے کی ٹیکنالوجی کی پیش رفت کی قیادت کی، پہلے مشاہدہ کریں پھر محدود مداخلت کے اصول کے قیام کو فروغ دیا</td><td>وقت کے پیچھے ہٹنے کی ٹیکنالوجی کے رہنما، وقت کے قوانین کے اصولوں کے مرتب کرنے والے</td></tr></tbody></table><h2 id="۳-اہم-تنظیمیں" tabindex="-1">۳. اہم تنظیمیں <a class="header-anchor" href="#۳-اہم-تنظیمیں" aria-label="Permalink to &quot;۳. اہم تنظیمیں&quot;">​</a></h2><h3 id="۳-۱-اعلیٰ-ترین-طاقت-کے-ادارے" tabindex="-1">۳.۱ اعلیٰ ترین طاقت کے ادارے <a class="header-anchor" href="#۳-۱-اعلیٰ-ترین-طاقت-کے-ادارے" aria-label="Permalink to &quot;۳.۱ اعلیٰ ترین طاقت کے ادارے&quot;">​</a></h3><table tabindex="0"><thead><tr><th>تنظیم کا نام</th><th>قیام کا وقت</th><th>بنیادی کام</th><th>تاریخی کردار</th></tr></thead><tbody><tr><td>اینکر کونسل</td><td>-900 سال</td><td>سمبیوسس تہذیب کا اعلیٰ ترین طاقت کا ادارہ، تمام نسلوں کے نمائندوں پر مشتمل متناسب طور پر، قانون سازی کی طاقت اور اہم معاملات پر فیصلہ سازی کی طاقت کا استعمال کرتا ہے</td><td>سمبیوسس تہذیب کا اعلیٰ ترین فیصلہ سازی ادارہ، تمام اہم قوانین اور حکمت عملیوں کے مرتب کرنے والے</td></tr><tr><td>سمبیوسس عملدرآمد کمیٹی</td><td>-900 سال</td><td>سمبیوسس تہذیب کا اعلیٰ ترین انتظامی ادارہ، آئین اور قوانین کے نفاذ، روزمرہ کی انتظامیہ کے لیے ذمہ دار</td><td>سمبیوسس تہذیب کا اعلیٰ ترین انتظامی ادارہ، قوانین اور پالیسیوں کے عمل کرنے والے</td></tr><tr><td>سمبیوسس عدالت</td><td>-900 سال</td><td>سمبیوسس تہذیب کا اعلیٰ ترین عدالتی ادارہ، آزادانہ طور پر عدالتی طاقت کا استعمال کرتا ہے، غیر آئینی جائزے اور اہم مقدمات کی سماعت کے لیے ذمہ دار</td><td>سمبیوسس تہذیب کا اعلیٰ ترین عدالتی ادارہ، قانون کی حاکمیت کے محافظ</td></tr><tr><td>اینکر نگرانی کمیٹی</td><td>-900 سال</td><td>آزاد نگرانی ادارہ، تمام طاقت کے اداروں کی نگرانی کے لیے ذمہ دار، طاقت کے غلط استعمال کو روکتا ہے</td><td>سمبیوسس تہذیب کا آزاد نگرانی ادارہ، طاقت کے توازن کا کلیدی حصہ</td></tr></tbody></table><h3 id="۳-۲-خصوصی-انتظامی-ادارے" tabindex="-1">۳.۲ خصوصی انتظامی ادارے <a class="header-anchor" href="#۳-۲-خصوصی-انتظامی-ادارے" aria-label="Permalink to &quot;۳.۲ خصوصی انتظامی ادارے&quot;">​</a></h3><table tabindex="0"><thead><tr><th>تنظیم کا نام</th><th>قیام کا وقت</th><th>بنیادی کام</th><th>تاریخی کردار</th></tr></thead><tbody><tr><td>طیارہ انتظامیہ</td><td>500 سال</td><td>طیارہ کوآرڈینیٹس کے عمومی بینک کی دیکھ بھال، سفر کی اجازت کی منظوری، بین طیاروں آثار قدیمہ کا انتظام، بین طیاروں سفارت کاروں کی ہم آہنگی کے لیے ذمہ دار</td><td>بین طیاروں تعامل کا مرکزی ادارہ، طیارہ دریافت کے منتظم</td></tr><tr><td>وقت کے قوانین کمیٹی</td><td>1000 سال</td><td>وقت کے پیچھے ہٹنے کے کاموں کی منظوری، وقت کے قوانین کی تحقیق، وقت کے پیراڈاکس کی روک تھام کی نگرانی کے لیے ذمہ دار</td><td>وقت کے پیچھے ہٹنے کے کاموں کی منظوری اور نگرانی کا ادارہ، وقت کے قوانین کی حفاظت کا محافظ</td></tr><tr><td>وقت کے قوانین آڈیٹ کمیٹی</td><td>1050 سال</td><td>وقت کے پیچھے ہٹنے کے کاموں کے بعد کے آڈیٹ کے لیے ذمہ دار، اس بات کی تصدیق کرنا کہ اس نے وقت کی لکیر میں غیر قابل کنٹرول خلل پیدا نہیں کیا ہے</td><td>وقت کے کاموں کا آزاد آڈیٹ ادارہ، وقت کے پیچھے ہٹنے کی حفاظت کی آخری دفاع</td></tr><tr><td>بین طیاروں اخلاقیات کمیٹی</td><td>600 سال</td><td>بین طیاروں اخلاقی اصولوں کی تدوین اور تشریح، اعلیٰ خطرے والے بین طیاروں تعامل کے منصوبوں کی منظوری، اخلاقی خلاف ورزی کی شکایات وصول کرتا ہے</td><td>بین طیاروں تعامل کا اخلاقی نگرانی ادارہ، تہذیب کی خود مختاری کا محافظ</td></tr><tr><td>علم کی واپسی آڈیٹ دفتر</td><td>850 سال</td><td>علم کی واپسی کے کاموں کے آڈیٹ کے لیے ذمہ دار، اس بات کی تصدیق کرنا کہ واپس کردہ مواد &quot;صرف علم کی واپسی&quot; کے اصول پر عمل کرتا ہے</td><td>علم کی واپسی کا آڈیٹ ادارہ، بین طیاروں آلودگی کی روک تھام کا کلیدی حصہ</td></tr></tbody></table><h3 id="۳-۳-تحقیق-اور-تعلیم-کے-ادارے" tabindex="-1">۳.۳ تحقیق اور تعلیم کے ادارے <a class="header-anchor" href="#۳-۳-تحقیق-اور-تعلیم-کے-ادارے" aria-label="Permalink to &quot;۳.۳ تحقیق اور تعلیم کے ادارے&quot;">​</a></h3><table tabindex="0"><thead><tr><th>تنظیم کا نام</th><th>قیام کا وقت</th><th>بنیادی کام</th><th>تاریخی کردار</th></tr></thead><tbody><tr><td>اینکر ریسرچ انسٹی ٹیوٹ</td><td>-8000 سال</td><td>اینکر میکانزم کی بنیادی تحقیق اور اطلاق کی ترقی، مصنوعی اینکر کی تعمیر اور دیکھ بھال</td><td>اینکر ٹیکنالوجی کا مرکزی تحقیقی ادارہ، سمبیوسس تہذیب کے ٹیکنالوجی کے ذرائع میں سے ایک</td></tr><tr><td>تین سو سیٹ نظام تنظیم کمیٹی</td><td>-500 سال</td><td>تین سو سیٹ اصل کھیت نظام کی کھدائی، تنظیم، تصدیق اور مسلسل بہتری</td><td>تین سو سیٹ نظام کی تنظیم اور دیکھ بھال کا ادارہ، کھیت کھولنے کی تکنیکی مدد</td></tr><tr><td>سمبیوسس یونیورسٹی لیگ</td><td>-700 سال</td><td>اعلیٰ تعلیم اور کھیت تعلیم کی مشترکہ تنظیم، اعلیٰ سطحی ہنر مندوں کی تربیت اور علمی تحقیق کے لیے ذمہ دار</td><td>سمبیوسس تہذیب کے اعلیٰ تعلیمی اداروں کی لیگ، ہنر مندوں کی تربیت اور علمی جدت کا مرکز</td></tr><tr><td>بین طیاروں آثار قدیمہ کالج</td><td>550 سال</td><td>بین طیاروں آثار قدیمہ کے پیشہ ورانہ ہنر مندوں کی تربیت، آثار قدیمہ کی ٹیکنالوجی کی تحقیق اور طریقہ کار کی جدت کرتا ہے</td><td>بین طیاروں آثار قدیمہ کی ہنر مندوں کی تربیت اور ٹیکنالوجی تحقیق کا مرکز</td></tr><tr><td>وقت کے قوانین ریسرچ انسٹی ٹیوٹ</td><td>950 سال</td><td>وقت کے قوانین کی بنیادی نظریاتی تحقیق اور وقت کے پیچھے ہٹنے کی ٹیکنالوجی کی تحقیق اور ترقی</td><td>وقت کے قوانین کی تحقیق کا مرکزی ادارہ، وقت کے پیچھے ہٹنے کی ٹیکنالوجی کا جائے پیدائش</td></tr></tbody></table><h3 id="۳-۴-فوجی-اور-سلامتی-تنظیمیں" tabindex="-1">۳.۴ فوجی اور سلامتی تنظیمیں <a class="header-anchor" href="#۳-۴-فوجی-اور-سلامتی-تنظیمیں" aria-label="Permalink to &quot;۳.۴ فوجی اور سلامتی تنظیمیں&quot;">​</a></h3><table tabindex="0"><thead><tr><th>تنظیم کا نام</th><th>قیام کا وقت</th><th>بنیادی کام</th><th>تاریخی کردار</th></tr></thead><tbody><tr><td>سمبیوسس دفاعی فوج</td><td>-850 سال</td><td>سمبیوسس تہذیب کی باقاعدہ دفاعی قوت، طیارہ دفاع اور بیرونی خطرات سے نمٹنے کے لیے ذمہ دار</td><td>سمبیوسس تہذیب کی بنیادی فوجی قوت، قومی سلامتی کے محافظ</td></tr><tr><td>طیارہ گشتی ٹولی</td><td>520 سال</td><td>دریافت کردہ طیاروں کی گشتی اور سلامتی کی نگرانی کے لیے ذمہ دار، بین طیاروں سلامتی واقعات سے نمٹتی ہے</td><td>بین طیاروں سلامتی کی پہلی صف کی قوت، طیارہ ترتیب کے محافظ</td></tr><tr><td>قوانین آلودگی ایمرجنسی ٹیم</td><td>600 سال</td><td>قوانین آلودگی اور توانائی آلودگی کے واقعات میں ہنگامی ردعمل اور آلودگی کے خاتمے کے لیے ذمہ دار</td><td>قوانین آلودگی کی ہنگامی ردعمل قوت، کائناتی ماحول کے محافظ</td></tr><tr><td>وقت پیراڈاکس ایمرجنسی گروپ</td><td>1020 سال</td><td>وقت پیراڈاکس واقعات میں ہنگامی ردعمل اور وجہ کی مرمت کے کاموں کے لیے ذمہ دار</td><td>وقت پیراڈاکس کی ہنگامی ردعمل قوت، وقت کی لکیر کے استحکام کی آخری ضمانت</td></tr></tbody></table><h3 id="۳-۵-شہری-اور-سماجی-تنظیمیں" tabindex="-1">۳.۵ شہری اور سماجی تنظیمیں <a class="header-anchor" href="#۳-۵-شہری-اور-سماجی-تنظیمیں" aria-label="Permalink to &quot;۳.۵ شہری اور سماجی تنظیمیں&quot;">​</a></h3><table tabindex="0"><thead><tr><th>تنظیم کا نام</th><th>قیام کا وقت</th><th>بنیادی کام</th><th>تاریخی کردار</th></tr></thead><tbody><tr><td>تمام نسلوں کی سمبیوسس کانفرنس</td><td>-2000 سال</td><td>تمام نسلوں کے نمائندوں کی باقاعدہ اجتماع، بین نسلی سمبیوسس کے معاملات پر بحث، ثقافتی تبادلے کو فروغ دینا</td><td>تمام نسلوں کے تبادلے کا اہم پلیٹ فارم، تمام نسلوں کی جمہوریہ کا پیش رو تنظیم</td></tr><tr><td>کھیت کار ایسوسی ایشن</td><td>-600 سال</td><td>کھیت کاروں کی پیشہ ورانہ خود مختاری تنظیم، کھیت کاروں کے حقوق کے تحفظ، پیشہ ورانہ اصولوں کی تدوین کے لیے ذمہ دار</td><td>کھیت کاروں کی خود مختاری تنظیم، کھیت کی صنعت کے معیاری بنانے کے فروغ دینے والے</td></tr><tr><td>صارفین ایسوسی ایشن</td><td>-650 سال</td><td>صارفین کے حقوق کے تحفظ کی تنظیم، صارفین کے حقوق کے دفاع، صارفین کی تعلیم، سماجی نگرانی کے لیے ذمہ دار</td><td>صارفین کے حقوق کے ترجمان، بازار ترتیب کے سماجی نگران</td></tr><tr><td>ماحولیاتی تحفظ لیگ</td><td>-550 سال</td><td>ماحولیاتی تحفظ کی شہری مشترکہ تنظیم، ماحولیاتی نگرانی، ماحولیاتی تعلیم، ماحولیاتی بحالی کے رضاکارانہ کام کے لیے ذمہ دار</td><td>ماحولیاتی تحفظ کی سماجی قوت، کائناتی ماحولیاتی تہذیب کے فروغ دینے والے</td></tr><tr><td>بین طیاروں دوستی ایسوسی ایشن</td><td>580 سال</td><td>بین طیاروں تہذیبوں کے درمیان دوستانہ تبادلے کو فروغ دینے والی شہری تنظیم، شہری سفارت کاری، ثقافتی تبادلے کے لیے ذمہ دار</td><td>بین طیاروں شہری سفارت کاری کی مرکزی قوت، تہذیبوں کے درمیان افہام و تفہیم کا پل</td></tr></tbody></table><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>اہم شخصیات اور تنظیمیں اینکر سمبیوسس تہذیب کی تاریخ کے زندہ کیریئر ہیں۔ قدیم فکری پیش رو سے لے کر معاصر تہذیب کے رہنما تک، اعلیٰ ترین طاقت کے اداروں سے لے کر شہری سماجی تنظیموں تک، ہر شخصیت اور تنظیم سمبیوسس تہذیب کے وسیع بیان میں ناقابل تلافی کردار ادا کرتی ہے۔ ان کی جدوجہد اور شراکت نے مل کر اینکر سمبیوسس تہذیب کے عدم سے وجود تک، چھوٹے سے بڑے تک، اپنے طیارے سے پوری کائنات تک کے شاندار مہاکاوی کو بنایا ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>70-عصر کی تقسیم کا عمومی جدول</li><li>49-حکمرانی کا ڈھانچہ اور طاقت کا توازن</li><li>77-تمام نسلوں کی جمہوریہ کی بنیاد</li></ul>',30)])])}const c=d(e,[["render",o]]);export{s as __pageData,c as default};
